WITH filtered AS (SELECT *, CAST(status_bits AS DOUBLE) AS status_bits_num FROM device_readings WHERE reading_ts >= DATE '2025-09-01'), cleaned AS (SELECT *, ROUND(temp_c / humidity, 2) AS temp_c_per_humidity FROM filtered WHERE reading_ts > TIMESTAMP '2025-09-01 11:00:00'), enriched AS (SELECT *, LEAD(temp_c_per_humidity, 2, 0) OVER (PARTITION BY device_code ORDER BY status_bits_num, id) AS next_temp_c_per_humidity, LEAD(temp_c_per_humidity, 2) OVER (ORDER BY humidity, id) AS next_temp_c_per_humidity_2, FIRST_VALUE(pressure) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_pressure, MIN(status_bits_num) OVER (PARTITION BY device_code) AS device_code_min_status_bits_num FROM cleaned), gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM enriched), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps), with_windows AS (SELECT *, AVG(is_new_session) OVER (PARTITION BY device_code ORDER BY session_no, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS is_new_session_avg_2, RANK() OVER w_grp AS next_temp_c_per_humidity_2_rank, SUM(next_temp_c_per_humidity_2) OVER (PARTITION BY device_code ORDER BY is_new_session, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_next_temp_c_per_humidity_2, FIRST_VALUE(temp_c) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_temp_c FROM sessionized WINDOW w_grp AS (PARTITION BY device_code ORDER BY next_temp_c_per_humidity_2 NULLS FIRST)), with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS is_new_session_2 FROM with_windows), sessions_device_readings AS (SELECT *, SUM(is_new_session_2) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), grouped AS (SELECT session_no, CASE WHEN first_known_temp_c >= 35.5 THEN 'LARGE' ELSE 'SMALL' END AS first_known_temp_c_tier, MIN(reading_ts) AS started_at, MAX(session_no) FILTER (WHERE device_code = 'DV-04') AS dv_04_max_session_no, MIN(reading_ts) AS started_at_2, MIN(reading_ts) AS first_seen, SIZE(COLLECT_SET(device_code)) AS num_device_codes, MAX(reading_ts) AS last_seen FROM sessions_device_readings GROUP BY ROLLUP (session_no, CASE WHEN first_known_temp_c >= 35.5 THEN 'LARGE' ELSE 'SMALL' END)) SELECT session_no, started_at, last_seen FROM grouped
